package com.tinyclass;

import com.tinyclass.auth.UserAccount;
import com.tinyclass.auth.UserAccountRepository;
import com.tinyclass.support.ApiBrowser;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.core.env.Environment;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.test.context.ActiveProfiles;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties="tinyclass.auth.attempt-limit=1000")
@ActiveProfiles("test")
class InvoiceTests {
    static final String TEACHER="invoice-teacher@example.test",PARENT="invoice-parent@example.test",UNVERIFIED="invoice-unverified@example.test",PASSWORD="Synthetic-invoice-password-2026";
    @Autowired Environment env;@Autowired JdbcTemplate jdbc;@Autowired JsonMapper json;@Autowired UserAccountRepository users;@Autowired PasswordEncoder passwords;
    UUID teacherId,parentId;String classroom,child,other,enrollment,otherEnrollment;List<UUID> attendance=new ArrayList<>(),sessions=new ArrayList<>();
    LocalDate today(){return LocalDate.now(ZoneId.of("Asia/Ho_Chi_Minh"));}
    LocalDate from(){return today().minusDays(7);}
    @BeforeEach void prepare()throws Exception {
        assertThat(jdbc.queryForObject("select current_database()",String.class)).isEqualTo("tinyclass_test");jdbc.execute("TRUNCATE users,audit_events CASCADE");
        teacherId=users.saveAndFlush(new UserAccount(TEACHER,passwords.encode(PASSWORD),"Invoice teacher","TEACHER")).getId();var p=new UserAccount(PARENT,passwords.encode(PASSWORD),"Invoice parent","PARENT");p.verifyEmail();parentId=users.saveAndFlush(p).getId();users.saveAndFlush(new UserAccount(UNVERIFIED,passwords.encode(PASSWORD),"Unverified","PARENT"));
        try(var t=login(TEACHER)){classroom=t.post("/classes",Map.of("name","Lớp lập phiếu","capacity",8)).data().path("id").stringValue();t.post("/classes/"+classroom+"/activate",Map.of("version",0));child=t.post("/students",Map.of("fullName","Bé phiếu học phí","internalNote","Private profile")).data().path("id").stringValue();other=t.post("/students",Map.of("fullName","Bé phiếu khác")).data().path("id").stringValue();enrollment=t.post("/classes/"+classroom+"/enrollments",Map.of("studentId",child)).data().path("id").stringValue();otherEnrollment=t.post("/classes/"+classroom+"/enrollments",Map.of("studentId",other)).data().path("id").stringValue();}
        jdbc.update("update class_enrollments set joined_at=now()-interval '90 days' where class_id=?",UUID.fromString(classroom));jdbc.update("insert into student_guardians(id,student_id,guardian_user_id,status,linked_at,created_at,updated_at) values(?,?,?,'ACTIVE',now(),now(),now())",UUID.randomUUID(),UUID.fromString(child),parentId);
        attendance.clear();sessions.clear();for(String state:List.of("PRESENT","LATE","ABSENT_EXCUSED","ABSENT_UNEXCUSED","UNMARKED","PRESENT","PRESENT"))seed(state,attendance.size()==5?"CANCELLED":attendance.size()==4?"SCHEDULED":"COMPLETED",attendance.size()!=6,enrollment,child);
        seed("PRESENT","COMPLETED",true,otherEnrollment,other);
    }
    void seed(String status,String sessionStatus,boolean active,String e,String c) {
        UUID session=UUID.randomUUID(),record=UUID.randomUUID();int offset=attendance.size();
        Instant start=from().plusDays(offset%7).atTime(9,0).atZone(ZoneId.of("Asia/Ho_Chi_Minh")).toInstant();
        boolean cancelled=sessionStatus.equals("CANCELLED"),marked=!status.equals("UNMARKED");
        jdbc.update("insert into class_sessions(id,class_id,title,starts_at,ends_at,status,roster_created_at,cancelled_at,cancellation_reason) values(?,?,'Buổi kiểm thử phiếu',?,?,?,now(),?,?)",session,UUID.fromString(classroom),java.sql.Timestamp.from(start),java.sql.Timestamp.from(start.plusSeconds(3600)),sessionStatus,cancelled?java.sql.Timestamp.from(Instant.now()):null,cancelled?"Synthetic cancelled session":null);
        jdbc.update("insert into attendance_records(id,session_id,student_id,enrollment_id,student_name_snapshot,status,is_active,note,family_note,marked_by,marked_at) values(?,?,?,?, 'Snapshot child',?,?,'Private attendance note','Public attendance note',?,?)",record,session,UUID.fromString(c),UUID.fromString(e),status,active,marked?teacherId:null,marked?java.sql.Timestamp.from(Instant.now()):null);
        sessions.add(session);attendance.add(record);
    }
    @Test void tooLargeSuggestedTotalCanBeSplitAndAllMoneyRemainsExact()throws Exception {
        try(var t=login(TEACHER)) {
            var a=agreement(t,"PER_SESSION",1_000_000_000_000L);var p=preview(t,a,from(),today(),null);
            assertThat(p.path("suggestedTotalVnd").isNull()).isTrue();assertThat(p.path("suggestedLines").size()).isEqualTo(3);
            var b=body(p);assertThat(t.post("/invoices",b).status()).isEqualTo(400);assertThat(jdbc.queryForObject("select count(*) from invoices",Integer.class)).isZero();
            lines(b).removeLast();lines(b).removeLast();assertThat(create(t,b).path("totalAmountVnd").longValue()).isEqualTo(1_000_000_000_000L);
        }
    }
    ApiBrowser login(String email)throws Exception{var b=new ApiBrowser("http://127.0.0.1:"+env.getProperty("local.server.port"),json);assertThat(b.post("/auth/login",Map.of("email",email,"password",PASSWORD)).status()).isEqualTo(200);return b;}
    JsonNode agreement(ApiBrowser t,String mode,long amount)throws Exception {var terms=new LinkedHashMap<String,Object>();terms.put("pricingMode",mode);terms.put("collectionTiming","AT_PERIOD_END");terms.put("publicTerms","Public agreement only");if(mode.equals("PER_SESSION")){terms.put("sessionUnitPriceVnd",amount);terms.put("chargeExcusedAbsence",false);terms.put("chargeUnexcusedAbsence",true);}else{terms.put(mode.equals("MONTHLY_FIXED")?"monthlyAmountVnd":"programTotalVnd",amount);terms.put("fixedFeeAbsenceRule","MANUAL_ADJUSTMENT");if(mode.equals("FULL_PROGRAM"))terms.put("programLabel","Khóa kiểm thử");}var r=t.post("/enrollments/"+enrollment+"/tuition-agreements",Map.of("clientRequestId",UUID.randomUUID(),"source","CUSTOM","terms",terms,"effectiveFrom",today().minusDays(60).toString(),"effectiveTo",today().plusDays(90).toString(),"internalNote","Private tuition conditions"));assertThat(r.status()).as("%s",r.body()).isEqualTo(201);return r.data();}
    JsonNode preview(ApiBrowser t,JsonNode a,LocalDate start,LocalDate end,String invoice)throws Exception{var body=new LinkedHashMap<String,Object>();body.put("agreementId",a.path("id").stringValue());body.put("periodStart",start.toString());body.put("periodEnd",end.toString());body.put("invoiceId",invoice);var r=t.post("/billing/previews",body);assertThat(r.status()).as("%s",r.body()).isEqualTo(200);return r.data();}
    Map<String,Object> body(JsonNode p){var r=new LinkedHashMap<String,Object>();r.put("clientRequestId",UUID.randomUUID());r.put("agreementId",p.path("agreementId").stringValue());r.put("periodStart",p.path("periodStart").stringValue());r.put("periodEnd",p.path("periodEnd").stringValue());r.put("previewKey",p.path("previewKey").stringValue());var lines=new ArrayList<Map<String,Object>>();for(JsonNode l:p.path("suggestedLines")){var line=new LinkedHashMap<String,Object>();for(String k:List.of("description","pricingBasis"))line.put(k,l.path(k).stringValue());for(String k:List.of("quantity","unitPriceVnd","discountVnd"))line.put(k,l.path(k).longValue());line.put("attendanceId",l.path("attendanceId").isNull()?null:l.path("attendanceId").stringValue());lines.add(line);}r.put("lines",lines);r.put("publicNote","Public invoice note");r.put("internalNote","Private invoice note");return r;}
    JsonNode create(ApiBrowser t,Map<String,Object> b)throws Exception{var r=t.post("/invoices",b);assertThat(r.status()).as("%s",r.body()).isEqualTo(201);return r.data();}
    String path(JsonNode i){return "/invoices/"+i.path("id").stringValue();}
    JsonNode issue(ApiBrowser t,JsonNode i)throws Exception{var r=t.post(path(i)+"/issue",Map.of("version",i.path("version").longValue(),"reviewKey",i.path("reviewKey").stringValue()));assertThat(r.status()).as("%s",r.body()).isEqualTo(200);return r.data();}
    @SuppressWarnings("unchecked") List<Map<String,Object>> lines(Map<String,Object> b){return (List<Map<String,Object>>)b.get("lines");}

    @Test void previewIsReadOnlyFiltersCompletedAttendanceAndUsesVietnamDateAndAbsenceRules()throws Exception{try(var t=login(TEACHER)){var a=agreement(t,"PER_SESSION",100000);var p=preview(t,a,from(),today(),null);assertThat(p.path("suggestedLines").size()).isEqualTo(3);assertThat(p.path("suggestedTotalVnd").longValue()).isEqualTo(300000);assertThat(p.path("candidates").size()).isEqualTo(7);assertThat(jdbc.queryForObject("select count(*) from invoices",Integer.class)).isZero();assertThat(jdbc.queryForObject("select count(*) from session_charge_entries",Integer.class)).isZero();assertThat(p.toString()).doesNotContain("Private attendance note","Private tuition conditions");}}
    @Test void createReservesOnceRetriesAreStableAndCancelledDraftNeverReachesFamily()throws Exception{try(var t=login(TEACHER);var p=login(PARENT)){var a=agreement(t,"PER_SESSION",100000);var b=body(preview(t,a,from(),today(),null));var i=create(t,b);assertThat(i.path("totalAmountVnd").longValue()).isEqualTo(300000);assertThat(i.path("sourceChanged").booleanValue()).isFalse();assertThat(jdbc.queryForObject("select count(*) from session_charge_entries where status='RESERVED'",Integer.class)).isEqualTo(3);assertThat(create(t,b).path("id").stringValue()).isEqualTo(i.path("id").stringValue());b.put("publicNote","Changed request");assertThat(t.post("/invoices",b).status()).isEqualTo(409);assertThat(p.get("/family/children/"+child+"/invoices").data().path("invoices").path("meta").path("totalElements").longValue()).isZero();assertThat(p.get("/family/children/"+child+path(i)).status()).isEqualTo(404);assertThat(t.post(path(i)+"/cancel",Map.of("version",0,"reason","Cancel draft")).status()).isEqualTo(200);assertThat(jdbc.queryForObject("select count(*) from session_charge_entries where status='VOIDED'",Integer.class)).isEqualTo(3);}}
    @Test void moneyQuantityDiscountSourceAndTotalAreValidatedAtomically()throws Exception{try(var t=login(TEACHER)){var a=agreement(t,"PER_SESSION",100000);var base=body(preview(t,a,from(),today(),null));for(String field:List.of("unitPriceVnd","discountVnd","quantity")){var bad=body(preview(t,a,from(),today(),null));lines(bad).getFirst().put(field,new BigDecimal("1.5"));assertThat(t.post("/invoices",bad).status()).isEqualTo(400);}lines(base).getFirst().put("discountVnd",100001);base.put("adjustmentReason","Private correction");assertThat(t.post("/invoices",base).status()).isEqualTo(400);base=body(preview(t,a,from(),today(),null));lines(base).getFirst().put("unitPriceVnd",90000);assertThat(t.post("/invoices",base).status()).isEqualTo(409);base=body(preview(t,a,from(),today(),null));lines(base).add(new LinkedHashMap<>(lines(base).getFirst()));assertThat(t.post("/invoices",base).status()).isEqualTo(409);base=body(preview(t,a,from(),today(),null));lines(base).getFirst().put("attendanceId",attendance.get(7));assertThat(t.post("/invoices",base).status()).isEqualTo(409);assertThat(jdbc.queryForObject("select count(*) from invoices",Integer.class)).isZero();}}
    @Test void manualAndDiscountAdjustmentsRequirePrivateReasonAndZeroIssuedInvoiceIsValid()throws Exception{try(var t=login(TEACHER)){var a=agreement(t,"PER_SESSION",100000);var b=body(preview(t,a,from(),today(),null));b.put("lines",List.of(Map.of("description","Miễn học phí","pricingBasis","OTHER","quantity",1,"unitPriceVnd",0,"discountVnd",0)));assertThat(t.post("/invoices",b).status()).isEqualTo(400);b.put("adjustmentReason","Cô miễn toàn bộ kỳ này");var i=issue(t,create(t,b));assertThat(i.path("totalAmountVnd").longValue()).isZero();assertThat(i.path("status").stringValue()).isEqualTo("ISSUED");}}
    @Test void draftEditRetainsOldLinesVoidsReservationsAndNeedsVersionAndReason()throws Exception{try(var t=login(TEACHER)){var a=agreement(t,"PER_SESSION",100000);var i=create(t,body(preview(t,a,from(),today(),null)));var b=body(preview(t,a,from(),today(),i.path("id").stringValue()));b.put("version",0);b.put("reason","Đối chiếu giảm một buổi");lines(b).removeLast();var r=t.write("PUT",path(i),b,true);assertThat(r.status()).as("%s",r.body()).isEqualTo(200);assertThat(r.data().path("totalAmountVnd").longValue()).isEqualTo(200000);assertThat(jdbc.queryForObject("select count(*) from invoice_lines",Integer.class)).isEqualTo(5);assertThat(jdbc.queryForObject("select count(*) from session_charge_entries where status='VOIDED'",Integer.class)).isEqualTo(3);assertThat(t.write("PUT",path(i),b,true).status()).isEqualTo(409);b.put("version",1);b.remove("reason");assertThat(t.write("PUT",path(i),b,true).status()).isEqualTo(400);}}
    @Test void emptyDraftCannotIssueAndIssuedContentsAreImmutableWhileSourceChangeOnlyWarns()throws Exception{try(var t=login(TEACHER)){var a=agreement(t,"PER_SESSION",100000);var b=body(preview(t,a,from(),today(),null));b.put("lines",List.of());var empty=create(t,b);assertThat(t.post(path(empty)+"/issue",Map.of("version",0,"reviewKey",empty.path("reviewKey").stringValue())).status()).isEqualTo(400);var i=issue(t,create(t,body(preview(t,a,from(),today(),null))));assertThat(jdbc.queryForObject("select count(*) from session_charge_entries where status='CHARGED'",Integer.class)).isEqualTo(3);assertThat(t.write("PUT",path(i),b,true).status()).isEqualTo(409);jdbc.update("update attendance_records set status='ABSENT_EXCUSED',version=version+1 where id=?",attendance.getFirst());var after=t.get(path(i)).data();assertThat(after.path("sourceChanged").booleanValue()).isTrue();assertThat(after.path("totalAmountVnd").longValue()).isEqualTo(300000);assertThat(after.path("lines").get(0).path("sourceSnapshot").path("attendanceStatus").stringValue()).isEqualTo("PRESENT");}}
    @Test void changedAttendanceOrAnotherReservationInvalidatesOldPreviewAndDraftIssue()throws Exception{try(var t=login(TEACHER)){var a=agreement(t,"PER_SESSION",100000);var b=body(preview(t,a,from(),today(),null));jdbc.update("update attendance_records set status='ABSENT_EXCUSED',version=version+1 where id=?",attendance.getFirst());assertThat(t.post("/invoices",b).status()).isEqualTo(409);var i=create(t,body(preview(t,a,from(),today(),null)));jdbc.update("update class_sessions set status='CANCELLED',cancelled_at=now(),cancellation_reason='Synthetic cancellation' where id=?",sessions.get(1));assertThat(t.post(path(i)+"/issue",Map.of("version",0,"reviewKey",i.path("reviewKey").stringValue())).status()).isEqualTo(409);assertThat(jdbc.queryForObject("select count(*) from invoices where status='ISSUED'",Integer.class)).isZero();}}
    @Test void concurrentSameRequestsReturnOneInvoiceAndOverlappingSessionsHaveOneHolder()throws Exception{try(var t=login(TEACHER);var otherBrowser=login(TEACHER);var pool=Executors.newFixedThreadPool(2)){var a=agreement(t,"PER_SESSION",100000);var b=body(preview(t,a,from(),today(),null));var start=new CountDownLatch(1);var first=pool.submit(()->{start.await();return t.post("/invoices",b);});var second=pool.submit(()->{start.await();return otherBrowser.post("/invoices",b);});start.countDown();var r1=first.get(20,TimeUnit.SECONDS);var r2=second.get(20,TimeUnit.SECONDS);assertThat(r1.status()).isEqualTo(201);assertThat(r2.status()).isEqualTo(201);assertThat(r1.data().path("id").stringValue()).isEqualTo(r2.data().path("id").stringValue());assertThat(jdbc.queryForObject("select count(*) from invoices",Integer.class)).isEqualTo(1);assertThat(jdbc.queryForObject("select count(*) from session_charge_entries where status='RESERVED'",Integer.class)).isEqualTo(3);}}
    @Test void concurrentDifferentRequestsForSameAttendanceCannotBothSave()throws Exception{try(var t=login(TEACHER);var otherBrowser=login(TEACHER);var pool=Executors.newFixedThreadPool(2)){var a=agreement(t,"PER_SESSION",100000);var p=preview(t,a,from(),today(),null);var b1=body(p);var b2=body(p);var start=new CountDownLatch(1);var first=pool.submit(()->{start.await();return t.post("/invoices",b1);});var second=pool.submit(()->{start.await();return otherBrowser.post("/invoices",b2);});start.countDown();assertThat(List.of(first.get(20,TimeUnit.SECONDS).status(),second.get(20,TimeUnit.SECONDS).status())).containsExactlyInAnyOrder(201,409);assertThat(jdbc.queryForObject("select count(*) from invoice_lines where is_active",Integer.class)).isEqualTo(3);}}
    @Test void cancelIssuedReleasesAttendanceKeepsFamilyHistoryAndRetryDoesNotCreateAgain()throws Exception{try(var t=login(TEACHER);var p=login(PARENT)){var a=agreement(t,"PER_SESSION",100000);var b=body(preview(t,a,from(),today(),null));var i=issue(t,create(t,b));assertThat(t.post(path(i)+"/cancel",Map.of("version",1,"reason","Private cancellation reason")).status()).isEqualTo(200);assertThat(preview(t,a,from(),today(),null).path("suggestedLines").size()).isEqualTo(3);assertThat(create(t,b).path("id").stringValue()).isEqualTo(i.path("id").stringValue());var pub=p.get("/family/children/"+child+path(i)).data();assertThat(pub.path("status").stringValue()).isEqualTo("CANCELLED");assertThat(pub.path("totalAmountVnd").longValue()).isEqualTo(300000);assertThat(pub.toString()).doesNotContain("Private cancellation reason");assertThat(t.get(path(i)+"/history").data().size()).isEqualTo(3);}}
    @Test void fullMonthSuggestionPartialMonthManualAndFixedPeriodOverlapAreExplicit()throws Exception{try(var t=login(TEACHER)){var a=agreement(t,"MONTHLY_FIXED",800000);LocalDate month=today().withDayOfMonth(1);var p=preview(t,a,month,month.withDayOfMonth(month.lengthOfMonth()),null);assertThat(p.path("suggestedTotalVnd").longValue()).isEqualTo(800000);var partial=preview(t,a,month.plusDays(1),month.plusDays(5),null);assertThat(partial.path("suggestedLines").isEmpty()).isTrue();assertThat(partial.path("warnings").toString()).contains("không tự chia");create(t,body(p));assertThat(t.post("/billing/previews",Map.of("agreementId",a.path("id").stringValue(),"periodStart",month.plusDays(1).toString(),"periodEnd",month.plusDays(5).toString())).status()).isEqualTo(409);}}
    @Test void fullProgramHasOneUncancelledInvoiceAcrossDifferentPeriodsAndCannotBeReplaced()throws Exception{try(var t=login(TEACHER)){var a=agreement(t,"FULL_PROGRAM",3000000);var upfront=body(preview(t,a,today(),today().plusDays(10),null));upfront.put("dueOn",today().minusDays(1).toString());var i=create(t,upfront);assertThat(i.path("dueOn").stringValue()).isEqualTo(today().minusDays(1).toString());assertThat(t.post("/billing/previews",Map.of("agreementId",a.path("id").stringValue(),"periodStart",today().plusDays(20).toString(),"periodEnd",today().plusDays(30).toString())).status()).isEqualTo(409);var replacement=new LinkedHashMap<String,Object>();replacement.put("clientRequestId",UUID.randomUUID());replacement.put("source","CUSTOM");replacement.put("terms",Map.of("pricingMode","FULL_PROGRAM","collectionTiming","UPFRONT","programTotalVnd",2000000,"programLabel","Khóa mới","fixedFeeAbsenceRule","KEEP_AGREED_AMOUNT"));replacement.put("effectiveFrom",today().plusDays(20).toString());replacement.put("effectiveTo",today().plusDays(90).toString());replacement.put("version",0);replacement.put("reason","Thử đổi tổng đã lập");assertThat(t.post("/tuition-agreements/"+a.path("id").stringValue()+"/replace",replacement).status()).isEqualTo(409);assertThat(t.post(path(i)+"/cancel",Map.of("version",0,"reason","Cancel before new program")).status()).isEqualTo(200);assertThat(t.post("/tuition-agreements/"+a.path("id").stringValue()+"/replace",replacement).status()).isEqualTo(201);}}
    @Test void invoiceGuardsAgreementDatesAndAttendanceWorkspaceReportsReferences()throws Exception{try(var t=login(TEACHER)){var a=agreement(t,"PER_SESSION",100000);var i=create(t,body(preview(t,a,from(),today().plusDays(2),null)));String ap="/tuition-agreements/"+a.path("id").stringValue();assertThat(t.post(ap+"/end",Map.of("version",0,"effectiveTo",today().toString(),"reason","Must preserve reserved dates")).status()).isEqualTo(409);assertThat(t.post(ap+"/end",Map.of("version",0,"effectiveTo",today().plusDays(2).toString(),"reason","Preserve billed period")).status()).isEqualTo(200);assertThat(t.get("/sessions/"+sessions.getFirst()+"/attendance").data().path("billingReferences").size()).isEqualTo(1);assertThat(t.get(path(i)).data().path("totalAmountVnd").longValue()).isEqualTo(300000);}}
    @Test void familyProjectionExcludesDraftPrivateAuditSourceVersionAndOtherChildAndRevokes()throws Exception{try(var t=login(TEACHER);var p=login(PARENT)){var a=agreement(t,"PER_SESSION",100000);var i=issue(t,create(t,body(preview(t,a,from(),today(),null))));var pub=p.get("/family/children/"+child+path(i));assertThat(pub.status()).isEqualTo(200);assertThat(pub.body().toString()).doesNotContain("Private","internalNote","adjustmentReason","cancelReason","sourceSnapshot","attendanceId","reviewKey","requestHash","version","teacherId");assertThat(p.get("/family/children/"+other+path(i)).status()).isEqualTo(404);jdbc.update("update class_enrollments set status='WITHDRAWN',ended_at=now() where id=?",UUID.fromString(enrollment));jdbc.update("update students set status='ARCHIVED' where id=?",UUID.fromString(child));assertThat(p.get("/family/children/"+child+path(i)).status()).isEqualTo(200);jdbc.update("update student_guardians set status='REVOKED',revoked_at=now() where student_id=?",UUID.fromString(child));assertThat(p.get("/family/children/"+child+"/invoices").status()).isEqualTo(404);assertThat(p.get("/family/children/"+child+path(i)).status()).isEqualTo(404);}}
    @Test void rolesCsrfPaginationAndBoundsAreEnforcedWithoutWrites()throws Exception{try(var t=login(TEACHER);var p=login(PARENT);var u=login(UNVERIFIED)){var a=agreement(t,"PER_SESSION",100000);var b=body(preview(t,a,from(),today(),null));assertThat(p.get("/invoices").status()).isEqualTo(403);assertThat(p.post("/invoices",b).status()).isEqualTo(403);assertThat(t.write("POST","/invoices",b,false).status()).isEqualTo(403);assertThat(u.get("/family/children/"+child+"/invoices").status()).isEqualTo(403);assertThat(t.get("/invoices?page=-1").status()).isEqualTo(400);assertThat(t.get("/invoices?status=PAID").status()).isEqualTo(400);assertThat(t.get("/invoices/"+UUID.randomUUID()).status()).isEqualTo(404);b.put("dueOn","1899-12-31");assertThat(t.post("/invoices",b).status()).isEqualTo(400);b.put("dueOn",null);b.put("periodEnd",today().plusDays(400).toString());assertThat(t.post("/invoices",b).status()).isEqualTo(400);assertThat(jdbc.queryForObject("select count(*) from invoices",Integer.class)).isZero();}}
}
